widgets.code:
function (settings, time, ctx) {
  // ---------- SETTINGS ----------
  var SHOW_BORDER  = settings.show_border.value;    // draw the frame around the mode
  var BORDER_WIDTH = settings.border_width.value;   // frame line thickness at the default 320x120 size; scales with the widget
  var BORDER_COLOR = settings.border_color.value;   // frame color
  var RADIUS       = settings.radius.value;         // corner radius at the default size (0 = sharp corners)
  var BG           = settings.background.value;     // box background; alpha 0 = no box
  var SHOW_ARROWS  = settings.show_arrows.value;    // chevrons pointing at the mode from both sides
  var ARROW_COLOR  = settings.arrow_color.value;    // chevron color
  var ARROW_SIZE   = settings.arrow_size.value;     // chevron height at the default size; scales with the widget
  var ARROW_WIDTH  = settings.arrow_width.value;    // chevron line thickness at the default size; scales with the widget
  var FONT         = settings.font.value;           // font family
  var SIZE         = settings.size.value;           // mode font size at the default size; scales with the widget
  var BOLD         = settings.bold.value;           // bold text
  var SHADOW       = settings.shadow.value;         // CSS text shadow ('' = none)
  var TEXT_COLOUR  = { all: settings.color.value }; // text color of every mode ("Color" setting). Give a mode its own color
                                                    // by adding its key here, e.g. { all: settings.color.value, FAILSAFE: '#ff3030', RTH: '#f2a93b' }
                                                    // keys: ACRO ANGLE HORIZON ALTHOLD ANGLE_HOLD POSHOLD CRUISE COURSE_HOLD RTH WP SEND_TO LAUNCH AUTOLAND MANUAL FAILSAFE TURTLE AUTOTUNE SOARING
  var ANIMATE      = settings.animate.value;        // carousel on a mode change: the new mode slides in from below, the old one out at the top
  var ANIM_MS      = settings.anim_ms.value;        // slide duration in ms (accelerates, then decelerates)
  var OPACITY      = settings.opacity.value;        // whole-widget opacity 0..1 (1 = opaque)
  // structural: modes in priority order, the first one whose bits are all set in activeFlightModeFlags is shown
  // (bits = activeFlightModeFlags bit numbers, key = TEXT_COLOUR key, label = the text shown; edit labels freely)
  var MODES = [
    { bits: [9],     key: 'FAILSAFE',    label: 'FAILSAFE' },
    { bits: [8],     key: 'MANUAL',      label: 'MANUAL' },
    { bits: [4],     key: 'RTH',         label: 'RTH' },
    { bits: [18],    key: 'AUTOLAND',    label: 'AUTOLAND' },
    { bits: [11],    key: 'WP',          label: 'WP' },
    { bits: [19],    key: 'SEND_TO',     label: 'SEND TO' },
    { bits: [7],     key: 'LAUNCH',      label: 'LAUNCH' },
    { bits: [5],     key: 'POSHOLD',     label: 'POSHOLD' },
    { bits: [12, 3], key: 'CRUISE',      label: 'CRUISE' },
    { bits: [12],    key: 'COURSE_HOLD', label: 'CRS HOLD' },
    { bits: [15],    key: 'TURTLE',      label: 'TURTLE' },
    { bits: [10],    key: 'AUTOTUNE',    label: 'AUTOTUNE' },
    { bits: [16],    key: 'SOARING',     label: 'SOARING' },
    { bits: [17],    key: 'ANGLE_HOLD',  label: 'ANGLE HOLD' },
    { bits: [3],     key: 'ALTHOLD',     label: 'ALTHOLD' },
    { bits: [1],     key: 'HORIZON',     label: 'HORIZON' },
    { bits: [0],     key: 'ANGLE',       label: 'ANGLE' }
  ];
  var NONE = { key: 'ACRO', label: 'ACRO' };        // shown when no mode bit is set
  // -------------------------------
  var W = ctx.width, H = ctx.height, scale = Math.min(W / 320, H / 120), i;

  // ---- mode from the flags word (activeFlightModeFlags is a plain integer in the CSV)
  function modeOf(v) {
    if (v === undefined || v === null || v === '') return null;
    var n = Number(v);
    if (isNaN(n)) return null;
    var a, b;
    for (a = 0; a < MODES.length; a++) {
      var ok = true;
      for (b = 0; b < MODES[a].bits.length; b++) if (Math.floor(n / Math.pow(2, MODES[a].bits[b])) % 2 !== 1) { ok = false; break; }
      if (ok) return MODES[a];
    }
    return NONE;
  }
  function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
  function colorOf(m) { return (m && TEXT_COLOUR[m.key]) || TEXT_COLOUR.all; }

  var col = ctx.columns[0];
  var cur = modeOf(ctx.raw(col));

  // ---- carousel: replay the recent history to find the last mode change (pure in time, so seeking and export agree)
  var prev = null, p = 1;
  if (ANIMATE && ANIM_MS > 0 && cur) {
    var sam = ctx.range(col, time - ANIM_MS - 1000, time, 2000) || [];
    var lastMode = null, changeT = null, before = null;
    for (i = 0; i < sam.length; i++) {
      if (sam[i].t > time) break;
      var m = modeOf(sam[i].v);
      if (!m) continue;
      if (lastMode && m.key !== lastMode.key) { changeT = sam[i].t; before = lastMode; }
      lastMode = m;
    }
    if (changeT !== null && before.key !== cur.key && time - changeT < ANIM_MS) {
      p = (time - changeT) / ANIM_MS;
      prev = before;
    }
  }
  var e = p < 0.5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2;   // ease-in-out: accelerate, then decelerate

  // ---- geometry (everything inside the border)
  var bw = SHOW_BORDER ? BORDER_WIDTH * scale : 0;
  var IW = W - 2 * bw, IH = H - 2 * bw, pad = 6 * scale;
  var asw = SHOW_ARROWS ? ARROW_WIDTH * scale : 0;
  var ah = SHOW_ARROWS ? Math.min(ARROW_SIZE * scale, IH - 2 * pad - asw) : 0;
  var ad = ah * 0.42;                                   // chevron depth
  var x0 = pad + asw / 2, cy = IH / 2;
  var tx = SHOW_ARROWS ? x0 + ad + asw / 2 + pad : pad;  // text area starts after the chevron
  var tw = IW - 2 * tx;
  var fs = SIZE * scale;
  // long names (FAILSAFE, ANGLE HOLD) shrink to the text area; both lines of a slide share one size
  var longest = Math.max((cur ? cur.label : '--').length, prev ? prev.label.length : 0);
  fs = Math.min(fs, tw / (longest * (BOLD ? 0.7 : 0.64)));

  var out = '<div style="position:relative;width:100%;height:100%;box-sizing:border-box;overflow:hidden;background:' + BG
    + ';border:' + bw.toFixed(2) + 'px solid ' + (SHOW_BORDER ? BORDER_COLOR : 'transparent')
    + ';border-radius:' + (RADIUS * scale).toFixed(1) + 'px;opacity:' + OPACITY + ';font-family:' + FONT + '">';

  if (SHOW_ARROWS && ah > 0) {
    var pts = function (x, dir) {                       // chevron: > at the left (dir 1), < at the right (dir -1)
      return x.toFixed(2) + ',' + (cy - ah / 2).toFixed(2) + ' ' + (x + dir * ad).toFixed(2) + ',' + cy.toFixed(2) + ' ' + x.toFixed(2) + ',' + (cy + ah / 2).toFixed(2);
    };
    out += '<svg width="' + IW.toFixed(0) + '" height="' + IH.toFixed(0) + '" style="position:absolute;left:0;top:0">'
      + '<polyline points="' + pts(x0, 1) + '" fill="none" stroke="' + ARROW_COLOR + '" stroke-width="' + asw.toFixed(2) + '" stroke-linecap="round" stroke-linejoin="round"/>'
      + '<polyline points="' + pts(IW - x0, -1) + '" fill="none" stroke="' + ARROW_COLOR + '" stroke-width="' + asw.toFixed(2) + '" stroke-linecap="round" stroke-linejoin="round"/>'
      + '</svg>';
  }

  var line = function (m, top) {
    return '<div style="position:absolute;left:0;width:100%;top:' + top.toFixed(2) + 'px;height:' + IH.toFixed(2) + 'px;line-height:' + IH.toFixed(2)
      + 'px;text-align:center;white-space:nowrap;font-size:' + fs.toFixed(1) + 'px;font-weight:' + (BOLD ? 'bold' : 'normal')
      + ';color:' + colorOf(m) + ';text-shadow:' + (SHADOW || 'none') + '">' + esc(m ? m.label : '--') + '</div>';
  };
  out += '<div style="position:absolute;left:' + tx.toFixed(2) + 'px;top:0;width:' + tw.toFixed(2) + 'px;height:' + IH.toFixed(2) + 'px;overflow:hidden">';
  if (prev) out += line(prev, -e * IH);                 // old mode leaves at the top
  out += line(cur, (1 - e) * IH);                       // new / current mode (arrives from below while sliding)
  out += '</div></div>';
  return out;
}
